        reviews.extend(page)
        page_index += 1
    if reviews:
        existing_ratings[song['song_id']] = reviews[0]['rating']

rating_summary = {
    'already_five': sum(1 for rating in existing_ratings.values() if rating == 5.0),
    'lower_than_five': sum(1 for rating in existing_ratings.values() if rating < 5.0),
    'missing': len(liked_songs) - len(existing_ratings)
}
print(rating_summary)
